example:
composition "Trim" { ample 1  tempo 96  master-seed 82 }

midi-clip phrase {
  chords C Am F G
  bars 4
}

synth source {
  wave triangle
  gain -9 dB
  from phrase.notes -> notes
}

trim tight {
  threshold -45 dB
  padding 50 ms
  from source.audio -> audio
}

master output {
  from tight.audio -> audio
}
